import java.io.*;
import java.util.*;
import java.util.regex.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            String pattern = "\\([\\w_]*\\)";
            Pattern r = Pattern.compile(pattern);
            String replaced = r.matcher(s).replaceAll("_");
            int longest = Arrays.stream(replaced.split("_")).mapToInt(String::length).max().orElse(0);
            long inside = 0;
            Matcher m = r.matcher(s);
            while (m.find()) {
                inside += countInside(m.group().substring(1, m.group().length() - 1));
            }
            out.println(longest + " " + inside);
        }

        private long countInside(String inner) {
            long count = 0;
            for (String part : inner.split("_")) {
                if (!part.isEmpty()) {
                    count++;
                }
            }
            return count;
        }
    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
